#include <iostream>
#include <cstring>
#include <cstdio>
#include <algorithm>

using namespace std;

const int N = 200010, M = 300010;

int a[N];
bool st[M], f[M];
int n;

int main()
{
    scanf("%d", &n);
    for (int i = 1; i <= n; i ++)
    {
        scanf("%d", &a[i]);
        st[a[i]] = 1;
    }

    for (int i = (1 << 18) - 1; i >= 0; i --)
        for (int j = 0; j < 18; j ++)
            if ((i & (1 << j)) == 0)
            {
                f[i] = f[i] | f[i | (1 << j)] | st[i | (1 << j)];
            }

    sort(a + 1, a + n + 1);
    int m = unique(a + 1, a + n + 1) - a - 1;

    int ans = m;
    for (int i = 1; i <= m; i ++)
        if (f[a[i]])
            ans --;
    printf("%d\n", ans);

    return 0;
}
